     9	public class PricingService {
    10	    public static class PricingResult {
    11	        public int nights;
    12	        public double nightlyRate;
    13	        public double subtotal;
    14	        public double discount;
    15	        public double total;
    16	
    17	        public PricingResult(int nights, double nightlyRate, double subtotal, double discount, double total) {
    18	            this.nights = nights;
    19	            this.nightlyRate = nightlyRate;
    20	            this.subtotal = subtotal;
    21	            this.discount = discount;
    22	            this.total = total;
    23	        }
    24	    }
    25	
    26	    public PricingResult calculatePrice(LocalDate checkIn, LocalDate checkOut, double baseNightlyRate, RatePlan ratePlan) {
    27	        int nights = DateUtils.calculateNights(checkIn, checkOut);
    28	
    29	        double nightlyRate = calculateNightlyRate(checkIn, baseNightlyRate);
    30	        double nightlyRateRounded = MoneyUtils.round(nightlyRate);
    31	
    32	        double subtotal = 0;
    33	        LocalDate current = checkIn;
    34	        while (current.isBefore(checkOut)) {
    35	            subtotal += nightlyRateRounded;
    36	            current = current.plusDays(1);
    37	        }
    38	        subtotal = MoneyUtils.round(subtotal);
    39	
    40	        double discountAmount = calculateDiscount(subtotal, ratePlan);
    41	        discountAmount = MoneyUtils.round(discountAmount);
    42	
    43	        double total = MoneyUtils.round(subtotal - discountAmount);
    44	
    45	        return new PricingResult(nights, nightlyRateRounded, subtotal, discountAmount, total);
    46	    }
    47	
    48	    private double calculateNightlyRate(LocalDate checkIn, double baseRate) {
    49	        if (DateUtils.isHighSeason(checkIn)) {
    50	            return baseRate * 1.20;
    51	        }
    52	        return baseRate;
    53	    }
    54	
    55	    private double calculateDiscount(double subtotal, RatePlan ratePlan) {
    56	        return subtotal * ratePlan.getDiscountRate();
    57	    }
    58	}
